-- Chong&Pan ordering v2 migration 004 (idempotent)
-- Images from owner ZIP (54 images); prices from existing cafe public menu as of 2026-10-12.
-- LINE ordering stays CLOSED; prices should be reconfirmed against Loyverse before opening.
-- Only add products that do not already exist; never overwrite existing prices/names/availability.
CREATE TABLE IF NOT EXISTS catalog_price_reviews (product_id TEXT PRIMARY KEY REFERENCES catalog(id), source TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 0, reviewed_at TEXT);

